# Reassign open follow-ups to an active manager and its entered delivery destination. @{nl="Wijs open opvolgtaken opnieuw toe aan een actieve beheerder en diens ingevoerde verzendbestemming."}
scenario reassign(account:Account,manager:user label=label_account_manager,email:email) by=account_manager label="Reassign account"@{nl="Klantdossier opnieuw toewijzen"}
 require can_work(actor,account.location) and staff(manager)
 do
  set account {manager,email}
  for followup in account.FollowUp as item where not item.done limit=100
   set followup {assignee=manager,email}
   cancel followup.id
   if followup.due>now
    schedule followup.id at=followup.due event=FollowUpDue {followup,revision=followup.version+1}
scenario arm on=FollowUp.create
 do
  if event.after.due>now
   schedule event.after.id at=event.after.due event=FollowUpDue {followup=event.after,revision=event.after.version}
scenario reschedule on=FollowUp.update
 do
  cancel event.after.id
  if not event.after.done and event.after.due>now
   schedule event.after.id at=event.after.due event=FollowUpDue {followup=event.after,revision=event.after.version}
scenario remind on=FollowUpDue
 require event.followup.version==event.revision and not event.followup.done and event.followup.parent.active
 do send Mail.send {to=event.followup.email,subject=format("Account follow-up"@{nl="Klantopvolging"},locale=null),body=event.followup.title} when=not event.followup.done and event.followup.parent.active as notice

code.draft/CanMaintain.can:93-99:
scenario generate on=every(1h)
 do
  for plan in Plan as p where p.active and not p.parent.retired and p.next_due<=local_date(now,p.parent.location.timezone) limit=100
   let occurrence=format("{plan}:{due}",{plan=plan.id,due=plan.next_due})
   if not any(plan.Inspection as inspection,inspection.occurrence==occurrence)
    create Inspection {parent=plan,occurrence,due=plan.next_due,checklist=plan.checklist,template_version=plan.revision,inspector=plan.assignee} as inspection
   set plan {next_due=add_days(plan.next_due,plan.cadence_days)}
